function Table({heads,rows,empty='Ничего не найдено',onRow}:{heads:string[],rows:{id:string,cells:ReactNode[]}[],empty?:string,onRow?:(id:string)=>void}){
 const [hidden,setHidden]=useState<number[]>([]);
 const [page,setPage]=useState(0),[size,setSize]=useState(20),[sort,setSort]=useState<{column:number,direction:number}|null>(null);
 const columnsKey=heads.join('|');useEffect(()=>{setHidden([]);setPage(0);setSort(null)},[columnsKey]);
 const cellText=(v:any):string=>v==null||typeof v==='boolean'?'':typeof v==='string'||typeof v==='number'?String(v):Array.isArray(v)?v.map(cellText).join(' '):cellText(v.props?.children);
 const sorted=sort?rows.slice().sort((a,b)=>{const x=cellText(a.cells[sort.column]),y=cellText(b.cells[sort.column]);return sort.direction*compareReportCells(x,y);}):rows;const n=Math.max(1,Math.ceil(rows.length/size)),p=Math.min(page,n-1);
 const exportRows=()=>{const active=heads.map((_,i)=>i).filter(i=>!hidden.includes(i)&&heads[i]);const csv='\uFEFF'+[active.map(i=>heads[i]),...sorted.map(r=>active.map(i=>cellText(r.cells[i])))].map(row=>row.map(csvCell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='vag-table-'+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 return <><div className="tablecontrols"><details><summary>Видимость столбцов</summary><div>{heads.map((h,i)=>h&&<label key={i}><input type="checkbox" checked={!hidden.includes(i)} onChange={()=>setHidden(hidden.includes(i)?hidden.filter(x=>x!==i):[...hidden,i])}/>{h}</label>)}</div></details><button type="button" className="mini" onClick={exportRows}><Download size={14}/> Экспорт таблицы CSV</button></div><div className="tablewrap"><table><thead><tr>{heads.map((h,i)=>hidden.includes(i)?null:<th key={i}>{h&&<button type="button" className="sorthead" onClick={()=>{setPage(0);setSort({column:i,direction:sort?.column===i?-sort.direction:1})}}>{h} <span>{sort?.column===i?(sort.direction===1?'↑':'↓'):'↕'}</span></button>}</th>)}</tr></thead><tbody>{sorted.slice(p*size,(p+1)*size).map(r=><tr key={r.id} onDoubleClick={()=>onRow?.(r.id)}>{r.cells.map((c,i)=>hidden.includes(i)?null:<td key={i}>{c}</td>)}</tr>)}</tbody></table>{!rows.length&&<div className="empty"><Search size={31}/><h3>{empty}</h3><p>Добавьте запись или измените параметры поиска</p></div>}</div><div className="pager"><span>Найдено: <b>{rows.length}</b></span><div><button disabled={!p} onClick={()=>setPage(0)}>«</button><button disabled={!p} onClick={()=>setPage(p-1)}>‹</button><span>{p+1} / {n}</span><button disabled={p>=n-1} onClick={()=>setPage(p+1)}>›</button><select aria-label="Строк на странице" value={size} onChange={e=>{setSize(+e.target.value);setPage(0)}}>{[10,20,50,100].map(n=><option key={n}>{n}</option>)}</select></div></div></>;
}
function Chart({s,from,to,profit=false,onSelect}:{s:State,from:string,to:string,profit?:boolean,onSelect?:(day:string)=>void}){
 const days=Array.from({length:10},(_,i)=>{const d=new Date(Date.now()+5*3600000-(9-i)*86400000).toISOString().slice(0,10);const t=totals(s,d,d);return {d,n:profit?t.profit:t.revenue}}).filter(x=>(!from||x.d>=from)&&(!to||x.d<=to));const max=Math.max(1,...days.map(x=>Math.abs(x.n)));
 return <div className="chart">{days.map(x=><button type="button" className="chartcol" key={x.d} title={x.d+': '+money(x.n)} aria-label={'Открыть '+(profit?'прибыль':'продажи')+' за '+x.d} onClick={()=>onSelect?.(x.d)}><b>{number(x.n)}</b><div className="column"><i style={{height:Math.max(2,Math.abs(x.n)/max*115),background:x.n<0?'#ef8373':profit?'#6ab49f':'#62a8d9'}}/></div><small>{x.d.slice(8)}.{x.d.slice(5,7)}</small></button>)}{!days.length&&<p>График показывает последние 10 дней; выбранный период вне этого диапазона.</p>}</div>;
}
