 async function submit(e:any){e.preventDefault();if(uploadingPhoto||busy)return;const clicked=e.nativeEvent.submitter?.value;const type=modal==='draft_edit'?(clicked==='post'?'draft_post':'draft_save'):modal;const initialPurchase=modal==='product'&&!form.id&&form.unit==='л'&&form.oilReceiptEnabled?{line:form.oilReceipt||{qty:1,price:0},draftId:returnTo?.modal==='draft_edit'?returnTo.form.id:undefined,partyId:form.oilSupplierId,date:form.date}:undefined;const next=await mutate({...form,type,lines,initialPurchase});if(!next)return;if(initialPurchase){const product=next.products.find(p=>!s.products.some(old=>old.id===p.id));const receipt=next.entries.find(e=>e.status==='draft'&&e.lines.some(l=>l.id===product?.id));if(receipt){setReturnTo(null);setItemSearch('');open('draft_edit',receipt);return;}}if(modal==='draft_new'){open('draft_edit',next.entries.at(-1));return;}if(returnTo){const back={...returnTo.form};if(modal==='party'){back.partyId=next.parties.at(-1)?.id;}let backLines=returnTo.lines;if(modal==='product'&&form.id){const product=next.products.find(p=>p.id===form.id);if(product)backLines=backLines.map((line:any)=>line.id===product.id?{...line,name:product.name}:line);}if(modal==='product'&&!form.id&&returnTo.modal==='draft_edit'){const product=next.products.find(p=>!s.products.some(old=>old.id===p.id));if(product&&!backLines.some((line:any)=>line.id===product.id)){backLines=[...backLines,{id:product.id,kind:'product',name:product.name,qty:1,price:product.cost,discount:0,expense:0,retail:product.price,wholesale:product.wholesale}];setItemSearch('');}}setModal(returnTo.modal);setForm(back);setLines(backLines);setReturnTo(null);}else setModal('');}
 async function exportJSON(){if(lock.current||!ready||modal)return;lock.current=true;setBusy(true);setError('');try{const backup=await fetchBackup(mode);download(JSON.stringify(backup,null,2),'vag-oil-'+mode+'-'+today()+'.json','application/json');setToast('Свежая резервная копия скачана');setTimeout(()=>setToast(''),2500)}catch(e){setError((e as Error).message)}finally{lock.current=false;setBusy(false)}}
 function download(content:string,name:string,mime:string){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function csv(){const goods=['Все товары','Товары с картинками','Мало на складе','Остатки по магазинам'].includes(tab);const rows:any[][]=goods?[['Код','Наименование','Артикул','Штрихкод','QR-код','Категория','Остаток','Оплаченный','Получен в долг','Нужно уточнить','Единица','Себестоимость','Розница','Опт'],...products.map(p=>[p.code,p.name,p.article,p.barcode,p.qrCode||'',p.category,p.qty,stockBalance(s,p.id).paid,stockBalance(s,p.id).credit,stockBalance(s,p.id).unknown,p.unit,p.cost,p.price,p.wholesale])]:[['Номер','Дата','Операция','Контрагент','Кассир','Статус','Сумма','Оплачено','Осталось','Комментарий'],...entries.map(e=>[e.number,date(e.date),docNames[e.type],e.party,actorLabel(e.cashier),e.status,e.total,e.paid,['sale','purchase'].includes(e.type)?debt(e):0,e.note])];download('\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n'),'vag-oil-'+today()+'.csv','text/csv;charset=utf-8')}
 const match=(v:string)=>v.toLowerCase().includes(query.toLowerCase());
 const inRange=(d:string)=>{const local=new Date(new Date(d).getTime()+5*3600000).toISOString();const day=local.slice(0,10);if(tab==='Покупка')return (!from||local.slice(0,16)>=from+'T'+fromClock)&&(!to||local.slice(0,16)<=to+'T'+toClock);return (!from||day>=from)&&(!to||day<=to)};
 const products=s.products.filter(p=>match([p.name,p.code,p.article,p.barcode,p.qrCode].join(' '))&&(!barcode||[p.barcode,p.qrCode].some(v=>(v||'').toLocaleLowerCase('ru').includes(barcode.toLocaleLowerCase('ru'))))&&(!cat||p.category===cat)&&(!favorites||p.favorite)&&(tab!=='Мало на складе'||p.qty<=p.min));
 const cashierHistory=['Продажи / касса','Возвраты клиентов'].includes(tab);
 const cashierOptions=Array.from(new Map(s.entries.flatMap(e=>e.cashier?[[e.cashier.id,e.cashier] as [string,SaleActor]]:[])).values()).sort((a,b)=>a.name.localeCompare(b.name,'ru'));
 const entries=s.entries.filter(e=>(!cashierHistory||!cashierFilter||(e.cashier?.id||'unknown')===cashierFilter)&&e.status!=='deleted'&&match([e.number,e.party,e.cashier?.name,e.cashier?.login,e.car,e.phone,e.note,String(e.total),e.lines.map(l=>l.name).join(' ')].join(' '))&&(!partyFilter||e.partyId===partyFilter)&&(!status||e.status===status)&&inRange(e.date));
 const filteredPayments=s.payments.filter(p=>match(paymentSearchText(p))&&inRange(p.date));
 const sumLines=round(lines.reduce((n,l)=>n+Number(l.qty||0)*Number(l.price||0)-Number(l.discount||0),0)),documentDiscount=form.discountMode==='percent'?round(sumLines*Number(form.discountValue||0)/100):Number(form.discountValue||0),total=round(sumLines-documentDiscount),purchaseExpenses=round(lines.reduce((n,l)=>n+Number(l.qty||0)*Number(l.expense||0),0));
 const lineCost=(l:any)=>{const net=Number(l.price||0)-Number(l.discount||0)/Number(l.qty||1);return net*(sumLines?total/sumLines:1)+Number(l.expense||0)};
 function applyPurchaseTool(){const value=Number(toolValue);if(!Number.isFinite(value)||value<0){setError('Введите положительное число');return}if(!lines.length){setError('Сначала добавьте товары');return}if(purchaseTool==='discount'){if(toolMode==='percent'&&value>100){setError('Скидка не может превышать 100%');return}const gross=lines.reduce((n,l)=>n+Number(l.qty)*Number(l.price),0);if(toolMode==='amount'&&value>gross){setError('Скидка превышает сумму товаров');return}let remaining=round(toolMode==='percent'?gross*value/100:value);const totalDiscount=remaining;setLines(lines.map((l,i)=>{const discount=i===lines.length-1?remaining:round(gross?totalDiscount*Number(l.qty)*Number(l.price)/gross:0);remaining=round(remaining-discount);return {...l,discount}}))}else if(purchaseTool==='expense'){const qty=lines.reduce((n,l)=>n+Number(l.qty),0);setLines(lines.map(l=>({...l,expense:qty?value/qty:0})))}else setLines(lines.map(l=>({...l,[markupTarget]:round(lineCost(l)*(1+value/100))})));setError('');setPurchaseTool('')}
 const field=(label:string,key:string,type='text',required=false)=><label>{label}<SafeInput type={type} required={required} min={type==='number'?0:undefined} step={type==='number'?'0.001':undefined} value={form[key]??''} onChange={e=>change(key,e.target.value)}/></label>;
 const accountField=<label>Касса<select required value={form.account||'cash'} onChange={e=>change('account',e.target.value)}>{s.accounts.map(a=><option key={a.id} value={a.id}>{a.name} · {money(balance(s,a.id))}</option>)}</select></label>;
