 const statusBadge=(e:Entry)=><span className={'badge '+(e.status==='posted'&&!e.cancelledAt?'greenbadge':e.status==='draft'?'amber':'gray')}>{e.cancelledAt?(e.type==='opening_stock'?'Ввод отменён':'Возврат отменён'):e.status==='posted'?'Проведено':e.status==='draft'?'Черновик':'Отменено'}</span>;
 const docs=(list:Entry[])=><Table heads={['№','Контрагент / клиент',...(cashierHistory?['Кассир']:[]),'Валюта','Сумма','Скидка','Оплачено','Долг','Статус','Дата','Комментарий','']} onRow={id=>{const e=s.entries.find(e=>e.id===id)!;e.status==='draft'?open('draft_edit',e):setDetailId(id)}} rows={list.slice().reverse().map(e=>({id:e.id,cells:[<button className="link" onClick={()=>e.status==='draft'?open('draft_edit',e):setDetailId(e.id)}>{e.number}</button>,<>{e.party}<small>{e.car}</small></>,...(cashierHistory?[<span>{actorLabel(e.cashier)}{e.cashier&&<small>{e.cashier.login}</small>}</span>]:[]),'TJS',number(e.total),number(e.discount),number(e.paid),<b className={debt(e)?'red':''}>{e.status==='posted'&&['sale','purchase'].includes(e.type)?number(debt(e)):'—'}</b>,statusBadge(e),date(e.date),e.note,posted(e)&&debt(e)>0&&['sale','purchase'].includes(e.type)?<button className="mini" onClick={()=>open('payment',{target:e.id,amount:debt(e),party:e.party})}>Оплатить</button>:null]}))}/>;
 const purchaseDocs=(list:Entry[])=><Table heads={['№','Магазин','Поставщик','Валюта','Товары до скидки','Скидка','Сумма накладной','Доп. расходы','Статус','Дата','Пользователь','Комментарий']} onRow={id=>{const e=s.entries.find(e=>e.id===id)!;e.status==='draft'?open('draft_edit',e):setDetailId(id)}} rows={list.slice().reverse().map(e=>({id:e.id,cells:[<button className="link" onClick={()=>e.status==='draft'?open('draft_edit',e):setDetailId(e.id)}>{e.number}</button>,s.settings.name,e.party,'🇹🇯 TJS',number(e.total+e.discount+e.lines.reduce((n,l)=>n+(l.discount||0),0)),<span className="red">{number(e.discount+e.lines.reduce((n,l)=>n+(l.discount||0),0))}</span>,<b className="purple">{number(e.total)}</b>,<span className="red">{number(e.expenses||s.entries.filter(x=>x.type==='expense'&&x.target===e.id).reduce((n,x)=>n+x.total,0))}</span>,statusBadge(e),date(e.date),'Руководитель',e.note||'—']}))}/>;
 function addLine(id:string,kind='product'){const p=kind==='service'?s.services.find(p=>p.id===id):s.products.find(p=>p.id===id);if(!p||lines.some(l=>l.id===id))return;setLines([...lines,{id,kind,name:p.name,discount:0,retail:(p as Product).price,wholesale:(p as Product).wholesale,qty:modal==='inventory'?(p as Product).qty:1,price:modal==='draft_edit'?(p as Product).cost:form.priceMode==='wholesale'?(p as Product).wholesale:p.price}]);setItemSearch('')}
