 const lineTable=<div className="tablewrap"><table className={modal==='draft_edit'?'editable purchaseLines':'editable'}><thead><tr><th>Код / наименование</th>{modal==='draft_edit'&&<th>Артикул</th>}<th>{modal==='inventory'?'Факт. остаток':'Количество'}</th><th>Ед.</th>{!['inventory','writeoff'].includes(modal)&&<><th>{modal==='draft_edit'?'Закуп. цена':'Цена'}</th>{modal==='draft_edit'&&<><th>Скидка строки</th><th>Расход / ед.</th><th>Себестоимость</th><th>Цена продажи</th><th>Цена оптовая</th><th>Наценка розн.</th><th>Наценка опт.</th></>}<th>Сумма</th></>}<th/></tr></thead><tbody>{lines.map((l,i)=>{const cost=lineCost(l);return <tr key={l.id}><td className="invoiceProductCell"><small>{s.products.find(p=>p.id===l.id)?.code}</small>{modal==='draft_edit'&&s.products.some(p=>p.id===l.id)?<button type="button" className="invoiceProductName" disabled={busy||uploadingPhoto} title="Двойное нажатие — изменить карточку товара" aria-label={'Изменить товар '+(l.name||'')} onDoubleClick={()=>void nested('product',s.products.find(p=>p.id===l.id))} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();void nested('product',s.products.find(p=>p.id===l.id))}}}>{l.name||s.products.find(p=>p.id===l.id)?.name}</button>:<span className="invoiceProductText">{l.name||s.products.find(p=>p.id===l.id)?.name}</span>}{modal==='draft_edit'&&<PackagingControls s={s} p={s.products.find(p=>p.id===l.id)} line={l} purchase compact disabled={busy} onChange={next=>setLines(lines.map((v,k)=>k===i?next:v))}/>}{['sale','writeoff'].includes(modal)&&l.kind!=='service'&&<SourcePicker s={s} p={s.products.find(p=>p.id===l.id)} line={l} includeDrafts={modal==='sale'} title={modal==='sale'?'Какой товар продаём':'Из какого остатка списать'} disabled={busy} onChange={next=>setLines(lines.map((v,k)=>k===i?next:v))}/>}{modal==='inventory'&&Number(l.qty)<(s.products.find(p=>p.id===l.id)?.qty||0)&&<SourcePicker s={s} p={s.products.find(p=>p.id===l.id)} line={{...l,qty:(s.products.find(p=>p.id===l.id)?.qty||0)-Number(l.qty)}} title="Из какого остатка убрать недостачу" disabled={busy} onChange={next=>setLines(lines.map((v,k)=>k===i?{...v,stockOrigin:next.stockOrigin,stockSplit:next.stockSplit}:v))}/>} {modal==='sale'&&<PackagingControls s={s} p={s.products.find(p=>p.id===l.id)} line={l} disabled={busy} onChange={next=>setLines(lines.map((v,k)=>k===i?next:v))}/>}</td>{modal==='draft_edit'&&<td className="invoiceArticleCell">{s.products.find(p=>p.id===l.id)?.article||'—'}</td>}<td><SafeInput aria-label={'Количество '+(l.name||i)} type="number" min={modal==='inventory'?0:s.products.find(p=>p.id===l.id)?.wholeOnly?1:0.001} step={s.products.find(p=>p.id===l.id)?.wholeOnly?1:0.001} readOnly={!!l.packaging} required value={l.qty} onChange={e=>setLines(lines.map((v,k)=>i===k?{...v,qty:e.target.value}:v))}/>{modal==='draft_edit'&&s.products.find(p=>p.id===l.id)?.unit==='л'&&<div className="invoicePackSummary">{l.packaging?<><b>{packageLabel(l)}</b><span>Всего: {number(Number(l.qty),3)} л</span></>:<span>В литрах, без упаковки</span>}</div>}</td><td>{s.products.find(p=>p.id===l.id)?.unit}</td>{!['inventory','writeoff'].includes(modal)&&<><td><SafeInput aria-label={'Цена '+(l.name||i)} type="number" min="0" step="0.01" readOnly={!!l.packaging} required value={l.price} onChange={e=>setLines(lines.map((v,k)=>i===k?{...v,price:e.target.value}:v))}/></td>{modal==='draft_edit'&&<><td><SafeInput type="number" min="0" step="0.01" aria-label={'Скидка '+l.name} value={l.discount||0} onChange={e=>setLines(lines.map((v,n)=>i===n?{...v,discount:e.target.value}:v))}/></td><td><SafeInput type="number" min="0" step="0.001" aria-label={'Расход '+l.name} value={l.expense||0} onChange={e=>setLines(lines.map((v,n)=>i===n?{...v,expense:e.target.value}:v))}/></td><td>{number(cost,3)}</td>{['retail','wholesale'].map(k=><td key={k}><SafeInput type="number" min="0" step="0.01" aria-label={k+' '+l.name} value={l[k]||0} onChange={e=>setLines(lines.map((v,n)=>i===n?{...v,[k]:e.target.value}:v))}/></td>)}<td>{cost>0?number((Number(l.retail)/cost-1)*100)+'%':'—'}</td><td>{cost>0?number((Number(l.wholesale)/cost-1)*100)+'%':'—'}</td></>}<td>{number(Number(l.qty)*Number(l.price)-Number(l.discount||0))}</td></>}<td><button type="button" className="icon" aria-label="Удалить строку" onClick={()=>setLines(lines.filter((_,k)=>k!==i))}><X size={16}/></button></td></tr>})}</tbody></table>{!lines.length&&<div className="empty compact">Добавьте товары в документ</div>}</div>;
 const primary=()=>{if(tab==='Покупка')open('draft_new');else if(['Все товары','Товары с картинками','Мало на складе','Остатки по магазинам'].includes(tab))open('product');else if(tab==='Услуги')open('service');else if(tab==='Контрагенты'||tab==='Клиенты')open('party',{kind:tab==='Контрагенты'?'supplier':'client'});else if(tab==='Оплата расходов')open('expense');else if(tab==='Получить доход')open('income');else if(tab==='Между своими счетами')open('transfer');else if(tab==='Списание товаров')open('writeoff');else if(tab==='Инвентаризация')open('inventory');else open('sale')};
